package com.bank.spark.model;

// Describes a write: total records, Spark partitions, and partitionBy cardinality.
public class WritePlan {
    private final String name;
    private final long records;
    private final int sparkPartitions;
    private final long partitionByCardinality;   // distinct values of partitionBy column
    private final long bytesPerRecord;

    public WritePlan(String name, long records, int sparkPartitions,
                     long partitionByCardinality, long bytesPerRecord) {
        this.name = name;
        this.records = records;
        this.sparkPartitions = sparkPartitions;
        this.partitionByCardinality = partitionByCardinality;
        this.bytesPerRecord = bytesPerRecord;
    }

    public String getName() { return name; }
    public long getRecords() { return records; }
    public int getSparkPartitions() { return sparkPartitions; }
    public long getPartitionByCardinality() { return partitionByCardinality; }
    public long getBytesPerRecord() { return bytesPerRecord; }
}
