package com.bank.spark.service;

import com.bank.spark.model.WritePlan;
import java.util.logging.Logger;

// Estimates output file count/size and recommends a fix for small files.
public class FileLayoutAnalyzer {

    private static final Logger log = Logger.getLogger(FileLayoutAnalyzer.class.getName());
    private static final long MIN_HEALTHY_FILE_MB = 64;

    // Files roughly = sparkPartitions × partitionByCardinality (one file per writer per dir).
    public long estimateFileCount(WritePlan p) {
        long dirs = Math.max(1, p.getPartitionByCardinality());
        return (long) p.getSparkPartitions() * dirs;
    }

    public long avgFileSizeMb(WritePlan p) {
        long totalMb = (p.getRecords() * p.getBytesPerRecord()) / (1024 * 1024);
        long files = Math.max(1, estimateFileCount(p));
        return totalMb / files;
    }

    public String recommend(WritePlan p) {
        long files = estimateFileCount(p);
        long avgMb = avgFileSizeMb(p);
        log.info(() -> p.getName() + ": estimated " + files + " files, avg " + avgMb + "MB each");

        if (avgMb >= MIN_HEALTHY_FILE_MB) {
            return "HEALTHY — files are adequately sized";
        }
        // Diagnose the dominant cause.
        if (p.getPartitionByCardinality() > 10000) {
            log.severe(() -> p.getName() + ": high-cardinality partitionBy ("
                    + p.getPartitionByCardinality() + " dirs) → file explosion");
            return "DROP high-cardinality partitionBy; partition by date, use maxRecordsPerFile";
        }
        if (p.getSparkPartitions() > 16) {
            log.warning(() -> p.getName() + ": too many Spark partitions for the data volume");
            return "COALESCE before write to fewer partitions; schedule compaction / Delta OPTIMIZE";
        }
        return "COMPACT periodically (streaming); use maxRecordsPerFile to bound file size";
    }
}
