package com.bank.spark;

import com.bank.spark.model.WritePlan;
import com.bank.spark.service.FileLayoutAnalyzer;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: estimate file layout and recommend small-files fixes.
public class SmallFilesDemo {

    private static final Logger log = Logger.getLogger(SmallFilesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FileLayoutAnalyzer analyzer = new FileLayoutAnalyzer();

        List<WritePlan> plans = List.of(
            // partitionBy transaction id (cardinality 1,000,000) → explosion.
            new WritePlan("partition-by-txnid", 1_000_000, 4, 1_000_000, 200),
            // 200 Spark partitions for little data → many small files.
            new WritePlan("over-partitioned-batch", 500_000, 200, 1, 200),
            // coalesced healthy write by date.
            new WritePlan("healthy-by-date", 500_000_000, 8, 30, 200));

        for (WritePlan p : plans) {
            String fix = analyzer.recommend(p);
            log.info(() -> "Plan " + p.getName() + " → " + fix);
        }
        log.info("Small-files demo complete.");
    }
}
